INSERT INTO "ResourceFaq" ("id","question","answer","tags","sortOrder","updatedAt") VALUES ('faq_where_pay','Where do I pay my state taxes?','Choose your state at the top of the Resource Center and open “Online tax account, filing & payments.” You''ll sign in and pay directly on the official state website — we never ask for your agency password. For federal taxes, use the IRS links under Federal Resources.',ARRAY['pay','payment','taxes','state','irs']::TEXT[],0,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ResourceFaq" ("id","question","answer","tags","sortOrder","updatedAt") VALUES ('faq_contacts','How do I find the right agency to contact?','Each resource card names the agency and links to its official website, where current contact information is published. If you''re not sure which office handles your question, use “Ask TTurner for Help” and we''ll point you in the right direction.',ARRAY['contact','agency','phone','office']::TEXT[],1,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ResourceFaq" ("id","question","answer","tags","sortOrder","updatedAt") VALUES ('faq_renew','How do I renew a business or liquor license?','Select your state and look under “Business Registration & Licenses” or “Liquor Licenses & Alcohol Taxes.” Renewals are handled on the official agency site. Local licenses may come from your city or county. Use “Request Licensing Assistance” if you''d like our help.',ARRAY['renew','renewal','license','liquor','alcohol','business license']::TEXT[],2,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ResourceFaq" ("id","question","answer","tags","sortOrder","updatedAt") VALUES ('faq_nonprofit','Can TTurner help me start a nonprofit?','Yes — we help establish nonprofits. Open “Nonprofit Services” and choose “Request Nonprofit Setup.” Your request goes securely to our office and appears in your portal Messages.',ARRAY['nonprofit','charity','501c3','setup']::TEXT[],3,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ResourceFaq" ("id","question","answer","tags","sortOrder","updatedAt") VALUES ('faq_upload','How do I send you documents?','Go to Documents in your portal and choose “Send us a document,” or attach a file when you use “Ask TTurner for Help.” Choose the tax year it belongs to (or “Not sure”). Files are checked for viruses before our team reviews them.',ARRAY['upload','documents','send','files']::TEXT[],4,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ResourceFaq" ("id","question","answer","tags","sortOrder","updatedAt") VALUES ('faq_help','How do I ask your office for help?','Use “Ask TTurner for Help” in any section of the Resource Center, or send a message from Messages in your portal. We''ll reply in your portal during office hours.',ARRAY['help','question','contact us','message']::TEXT[],5,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ResourceFaq" ("id","question","answer","tags","sortOrder","updatedAt") VALUES ('faq_sam','Does it cost anything to register on SAM.gov?','Registering your business on SAM.gov is free on the official government site. If you''d like TTurner & Associates to help with registration or renewal, our service fee is separate. Use “Request SAM.gov Assistance” under Federal Resources.',ARRAY['sam.gov','sam','uei','federal contracts','registration']::TEXT[],6,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "ResourceFaq" ("id","question","answer","tags","sortOrder","updatedAt") VALUES ('faq_refund','How do I check on my refund?','For a federal refund, use the IRS “Where''s My Refund?” link under Federal Resources. For a state refund, select your state and open “Where''s my state refund?” You may need information from your filed return. We can''t see or change refund status.',ARRAY['refund','where''s my refund','status']::TEXT[],7,CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
